<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';require_user();$title='Withdraw';$u=current_user();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$amount=(float)post('amount',0);$bank=trim((string)post('account'));$bal=(float)$u['balance'];if($amount<=0||$amount>$bal)flash('danger','Insufficient available balance or invalid amount.');else{db()->beginTransaction();try{dbq('UPDATE users SET balance=balance-? WHERE id=?',[$amount,user_id()]);dbq('INSERT INTO withdraw_logs(user_id,method_id,transaction_id,wallet_id,currency_id,amount,charge,net_amount,send_details,message,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,0,NOW(),NOW())',[user_id(),0,trx(),null,null,$amount,0,$amount,$bank,'']);db()->commit();flash('success','Withdrawal request submitted.');redirect('index.php?page=withdrawals');}catch(Throwable $e){db()->rollBack();flash('danger','Could not process request.');}}}require __DIR__.'/includes/header.php';?><div class="card"><h1>Withdraw Funds</h1><p class="muted">Available: ₦<?=money($u['balance']??0)?></p><form method="post"><?=csrf_field()?><div class="field"><label>Amount</label><input type="number" name="amount" step="0.01" min="1" required></div><div class="field"><label>Bank/account details</label><textarea name="account" required><?=e($u['accountname']??'')?></textarea></div><br><button class="btn">Request withdrawal</button></form></div><?php require __DIR__.'/includes/footer.php';?>